    this.principalRole = UserRole.supplier,
    this.blocked = false,
    this.roleLabelOverride,
  });

  final String id;
  final String name;
  final String phone;
  final AdminUserKind kind;
  final String avatarUrl;
  final UserRole principalRole;
  final bool blocked;
  final String? roleLabelOverride;

  factory AdminUserListEntry.fromJson(Map<String, dynamic> json) {
    final source = (json['source'] as String? ?? '').trim().toLowerCase();
    final principalRole = userRoleFromJson(
      json['principal_role'] as String? ?? source,
    );
    final kind = source == 'worker'
        ? AdminUserKind.worker
        : source == 'werka' || principalRole == UserRole.werka
            ? AdminUserKind.werka
            : principalRole == UserRole.materialTaminotchi
                ? AdminUserKind.materialTaminotchi
                : source == 'customer' || principalRole == UserRole.customer
                    ? AdminUserKind.customer
                    : principalRole == UserRole.qolipchi
                        ? AdminUserKind.qolipchi
                        : principalRole == UserRole.boyoqchi
                            ? AdminUserKind.boyoqchi
                            : AdminUserKind.supplier;
    final entityRef = (json['entity_ref'] as String? ?? '').trim();
    final rawId = (json['id'] as String? ?? '').trim();
    return AdminUserListEntry(
      id: entityRef.isNotEmpty ? entityRef : rawId,
      name: json['name'] as String? ?? '',
      phone: json['phone'] as String? ?? '',
      kind: kind,
      avatarUrl: json['avatar_url'] as String? ?? '',
      principalRole: principalRole,
      blocked: json['blocked'] as bool? ?? false,
      roleLabelOverride: json['role_label'] as String?,
    );
  }

  String get roleLabel {
    final override = roleLabelOverride?.trim() ?? '';
    if (override.isNotEmpty) {
      return override;
    }
    return kind == AdminUserKind.werka
        ? 'Werka'
        : kind == AdminUserKind.customer
            ? 'Customer'
            : kind == AdminUserKind.qolipchi
                ? 'Qolipchi'
                : kind == AdminUserKind.boyoqchi
                    ? 'Bo‘yoqchi'
                    : kind == AdminUserKind.materialTaminotchi
                        ? 'Material taminotchisi'
                        : kind == AdminUserKind.worker
                            ? userRoleLabel(principalRole)
                            : 'Supplier';
  }
}

DispatchStatus parseDispatchStatus(String raw) {
  switch (raw.trim().toLowerCase()) {
    case 'accepted':
      return DispatchStatus.accepted;
    case 'partial':
      return DispatchStatus.partial;
    case 'rejected':
      return DispatchStatus.rejected;
    case 'cancelled':
      return DispatchStatus.cancelled;
    case 'draft':
      return DispatchStatus.draft;
    default:
      return DispatchStatus.pending;
  }
}
